package consumer;
import System.Exception;import java.nio.file.*;import java.util.*;import java.lang.reflect.*;
public class ExceptionNonvirtualMemberBoundariesProbe{
 static Class<?> type(String n)throws ClassNotFoundException{return n.equals("int")?int.class:n.equals("void")?void.class:Class.forName(n);}static void check(boolean b,String c){if(!b)throw new AssertionError(c);}
 public static void main(String[] args)throws java.lang.Exception{int methods=0,values=0,groups=0;for(String line:Files.readAllLines(Path.of(args[0]))){String[] p=line.split("\t",-1);if(p[0].equals("M")){String[] names=p[3].isEmpty()?new String[0]:p[3].split(",");Class<?>[] parameters=new Class<?>[names.length];for(int i=0;i<names.length;i++)parameters[i]=type(names[i]);Method method=Exception.class.getDeclaredMethod(p[1],parameters);check(Modifier.isPublic(method.getModifiers())&&!Modifier.isStatic(method.getModifiers()),"visibility "+line);check(method.getDeclaringClass()==Exception.class,"owner "+line);check(Modifier.isFinal(method.getModifiers())!=p[4].equals("1"),"dispatch "+line);check(method.getReturnType()==type(p[2])&&Arrays.equals(method.getParameterTypes(),parameters),"signature "+line);groups+=4;methods++;continue;}Exception inner=p[2].equals("1")?new Exception("inner-value"):null;Exception value=(Exception)Class.forName(p[1]).getConstructor(String.class,Exception.class).newInstance(new Object[]{"outer-value",inner});check((value.get_InnerException()==inner)==p[3].equals("1"),"inner identity "+line);check(value.GetType().get_FullName().equals(p[4]),"runtime type "+line);check((value.get_TargetSite()==null)==p[5].equals("1"),"unthrown target "+line);groups+=3;values++;}java.lang.System.out.println("PASS exception member boundaries methods="+methods+" values="+values+" groups="+groups);}
}
